package com.example.a2hauto.auth;

import android.text.TextUtils;

import androidx.annotation.NonNull;

import com.example.a2hauto.api.ApiClient;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.auth.LoginRequest;
import com.example.a2hauto.model.auth.RegisterRequest;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.util.List;
import java.util.Map;

import okhttp3.ResponseBody;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class AuthRepository {

    public interface AuthCallback {
        void onSuccess(String token, String message);

        void onError(String message);
    }

    private final ApiService apiService;

    public AuthRepository() {
        this(ApiClient.getApiService());
    }

    public AuthRepository(ApiService apiService) {
        this.apiService = apiService;
    }

    public void login(String phoneNumber, String password, @NonNull AuthCallback callback) {
        LoginRequest request = new LoginRequest(AuthValidator.normalizePhone(phoneNumber), password);
        apiService.login(request).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Response<ApiResponse<JsonElement>> response) {
                handleResponse(response, callback);
            }

            @Override
            public void onFailure(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Throwable throwable) {
                callback.onError(getFailureMessage(throwable));
            }
        });
    }

    public void register(String fullName, String phoneNumber, String password, @NonNull AuthCallback callback) {
        RegisterRequest request = new RegisterRequest(fullName.trim(), AuthValidator.normalizePhone(phoneNumber), password);
        apiService.register(request).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Response<ApiResponse<JsonElement>> response) {
                handleResponse(response, callback);
            }

            @Override
            public void onFailure(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Throwable throwable) {
                callback.onError(getFailureMessage(throwable));
            }
        });
    }

    private void handleResponse(Response<ApiResponse<JsonElement>> response, AuthCallback callback) {
        ApiResponse<JsonElement> body = response.body();

        if (response.isSuccessful() && body != null && body.isSuccess()) {
            callback.onSuccess(extractData(body.getData()), resolveMessage(body.getMessage()));
            return;
        }

        callback.onError(resolveErrorMessage(response, body));
    }

    private String resolveErrorMessage(Response<ApiResponse<JsonElement>> response, ApiResponse<JsonElement> body) {
        if (body != null) {
            List<String> errors = body.getErrors();
            if (errors != null && !errors.isEmpty() && !TextUtils.isEmpty(errors.get(0))) {
                return errors.get(0);
            }

            if (!TextUtils.isEmpty(body.getMessage())) {
                return body.getMessage();
            }
        }

        try (ResponseBody errorBody = response.errorBody()) {
            if (errorBody != null) {
                String rawError = errorBody.string();
                if (!TextUtils.isEmpty(rawError)) {
                    String parsedMessage = extractMessageFromRawError(rawError);
                    if (!TextUtils.isEmpty(parsedMessage)) {
                        return parsedMessage;
                    }
                    return rawError;
                }
            }
        } catch (IOException ignored) {
            // Fallback to generic message below.
        }

        return "Không thể kết nối tới dịch vụ xác thực. Vui lòng thử lại.";
    }

    private String resolveMessage(String message) {
        return TextUtils.isEmpty(message) ? "Thao tác thành công." : message;
    }

    private String extractData(JsonElement data) {
        if (data == null || data.isJsonNull()) {
            return "";
        }

        if (data.isJsonPrimitive()) {
            return data.getAsString();
        }

        return data.toString();
    }

    private String getFailureMessage(Throwable throwable) {
        if (throwable == null || TextUtils.isEmpty(throwable.getMessage())) {
            return "Không thể kết nối tới dịch vụ xác thực. Vui lòng thử lại.";
        }
        return "Lỗi kết nối: " + throwable.getMessage();
    }

    private String extractMessageFromRawError(String rawError) {
        try {
            JsonElement jsonElement = new JsonParser().parse(rawError);
            if (!jsonElement.isJsonObject()) {
                return rawError;
            }

            JsonObject jsonObject = jsonElement.getAsJsonObject();

            if (jsonObject.has("message") && !jsonObject.get("message").isJsonNull()) {
                String message = jsonObject.get("message").getAsString();
                if (!TextUtils.isEmpty(message)) {
                    return message;
                }
            }

            if (jsonObject.has("errors") && jsonObject.get("errors").isJsonObject()) {
                JsonObject errorsObject = jsonObject.getAsJsonObject("errors");
                for (Map.Entry<String, JsonElement> entry : errorsObject.entrySet()) {
                    JsonElement value = entry.getValue();
                    if (value != null && value.isJsonArray() && value.getAsJsonArray().size() > 0) {
                        return value.getAsJsonArray().get(0).getAsString();
                    }
                }
            }

            if (jsonObject.has("title") && !jsonObject.get("title").isJsonNull()) {
                String title = jsonObject.get("title").getAsString();
                if (!TextUtils.isEmpty(title)) {
                    return title;
                }
            }
        } catch (Exception ignored) {
            // Keep original raw error fallback.
        }

        return rawError;
    }
}

package com.example.a2hauto.auth;

import android.text.TextUtils;

import androidx.annotation.NonNull;

import com.example.a2hauto.api.ApiClient;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.auth.LoginRequest;
import com.example.a2hauto.model.auth.RegisterRequest;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.util.List;
import java.util.Map;

import okhttp3.ResponseBody;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class AuthRepository {

    public interface AuthCallback {
        void onSuccess(String token, String message);

        void onError(String message);
    }

    private final ApiService apiService;

    public AuthRepository() {
        this(ApiClient.getApiService());
    }

    public AuthRepository(ApiService apiService) {
        this.apiService = apiService;
    }

    public void login(String phoneNumber, String password, @NonNull AuthCallback callback) {
        LoginRequest request = new LoginRequest(AuthValidator.normalizePhone(phoneNumber), password);
        apiService.login(request).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Response<ApiResponse<JsonElement>> response) {
                handleResponse(response, callback);
            }

            @Override
            public void onFailure(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Throwable throwable) {
                callback.onError(getFailureMessage(throwable));
            }
        });
    }

    public void register(String fullName, String phoneNumber, String password, @NonNull AuthCallback callback) {
        RegisterRequest request = new RegisterRequest(fullName.trim(), AuthValidator.normalizePhone(phoneNumber), password);
        apiService.register(request).enqueue(new Callback<>() {
            @Override
            public void onResponse(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Response<ApiResponse<JsonElement>> response) {
                handleResponse(response, callback);
            }

            @Override
            public void onFailure(@NonNull Call<ApiResponse<JsonElement>> call, @NonNull Throwable throwable) {
                callback.onError(getFailureMessage(throwable));
            }
        });
    }

    private void handleResponse(Response<ApiResponse<JsonElement>> response, AuthCallback callback) {
        ApiResponse<JsonElement> body = response.body();

        if (response.isSuccessful() && body != null && body.isSuccess()) {
            callback.onSuccess(extractData(body.getData()), resolveMessage(body.getMessage()));
            return;
        }

        callback.onError(resolveErrorMessage(response, body));
    }

    private String resolveErrorMessage(Response<ApiResponse<JsonElement>> response, ApiResponse<JsonElement> body) {
        if (body != null) {
            List<String> errors = body.getErrors();
            if (errors != null && !errors.isEmpty() && !TextUtils.isEmpty(errors.get(0))) {
                return errors.get(0);
            }

            if (!TextUtils.isEmpty(body.getMessage())) {
                return body.getMessage();
            }
        }

        try (ResponseBody errorBody = response.errorBody()) {
            if (errorBody != null) {
                String rawError = errorBody.string();
                if (!TextUtils.isEmpty(rawError)) {
                    String parsedMessage = extractMessageFromRawError(rawError);
                    if (!TextUtils.isEmpty(parsedMessage)) {
                        return parsedMessage;
                    }
                    return rawError;
                }
            }
        } catch (IOException ignored) {
            // Fallback to generic message below.
        }

        return "Không thể kết nối tới dịch vụ xác thực. Vui lòng thử lại.";
    }

    private String resolveMessage(String message) {
        return TextUtils.isEmpty(message) ? "Thao tác thành công." : message;
    }

    private String extractData(JsonElement data) {
        if (data == null || data.isJsonNull()) {
            return "";
        }

        if (data.isJsonPrimitive()) {
            return data.getAsString();
        }

        // Nếu data là JSON object, tìm field "token"
        if (data.isJsonObject()) {
            JsonObject jsonObject = data.getAsJsonObject();
            if (jsonObject.has("token") && !jsonObject.get("token").isJsonNull()) {
                return jsonObject.get("token").getAsString();
            }
        }

        return data.toString();
    }

    private String getFailureMessage(Throwable throwable) {
        if (throwable == null || TextUtils.isEmpty(throwable.getMessage())) {
            return "Không thể kết nối tới dịch vụ xác thực. Vui lòng thử lại.";
        }
        return "Lỗi kết nối: " + throwable.getMessage();
    }

    private String extractMessageFromRawError(String rawError) {
        try {
            JsonElement jsonElement = new JsonParser().parse(rawError);
            if (!jsonElement.isJsonObject()) {
                return rawError;
            }

            JsonObject jsonObject = jsonElement.getAsJsonObject();

            if (jsonObject.has("message") && !jsonObject.get("message").isJsonNull()) {
                String message = jsonObject.get("message").getAsString();
                if (!TextUtils.isEmpty(message)) {
                    return message;
                }
            }

            if (jsonObject.has("errors") && jsonObject.get("errors").isJsonObject()) {
                JsonObject errorsObject = jsonObject.getAsJsonObject("errors");
                for (Map.Entry<String, JsonElement> entry : errorsObject.entrySet()) {
                    JsonElement value = entry.getValue();
                    if (value != null && value.isJsonArray() && value.getAsJsonArray().size() > 0) {
                        return value.getAsJsonArray().get(0).getAsString();
                    }
                }
            }

            if (jsonObject.has("title") && !jsonObject.get("title").isJsonNull()) {
                String title = jsonObject.get("title").getAsString();
                if (!TextUtils.isEmpty(title)) {
                    return title;
                }
            }
        } catch (Exception ignored) {
            // Keep original raw error fallback.
        }

        return rawError;
    }
}

package com.example.a2hauto;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.FrameLayout;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.example.a2hauto.adapter.CategoryAdapter;
import com.example.a2hauto.api.ApiService;
import com.example.a2hauto.auth.AuthInterceptor;
import com.example.a2hauto.model.ApiResponse;
import com.example.a2hauto.model.ItemType;
import java.util.ArrayList;
import java.util.List;
import okhttp3.OkHttpClient;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import retrofit2.Retrofit;
import retrofit2.converter.gson.GsonConverterFactory;

public class ChooseCategoryActivity extends AppCompatActivity {

    private RecyclerView rvCategories;
    private CategoryAdapter adapter;
    private ProgressBar progressBar;
    private ApiService apiService;
    private FrameLayout bottomNavContainer;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_choose_category);

        rvCategories = findViewById(R.id.rvCategories);
        progressBar = findViewById(R.id.progressBar);
        bottomNavContainer = findViewById(R.id.bottomNavContainer);

        rvCategories.setLayoutManager(new LinearLayoutManager(this));
        adapter = new CategoryAdapter(new ArrayList<>(), this::onCategorySelected);
        rvCategories.setAdapter(adapter);

        initRetrofit();
        setupBottomNavigation();
        fetchItemTypes();
    }

    private void initRetrofit() {
        // Tạo OkHttpClient với AuthInterceptor
        OkHttpClient.Builder httpClient = new OkHttpClient.Builder();
        httpClient.addInterceptor(new AuthInterceptor(this));

        apiService = new Retrofit.Builder()
                .baseUrl("http://vehiclemarket.runasp.net/")
                .client(httpClient.build())
                .addConverterFactory(GsonConverterFactory.create())
                .build()
                .create(ApiService.class);
    }

    private void setupBottomNavigation() {
        // Inflate the bottom navigation bar layout
        View navView = getLayoutInflater().inflate(R.layout.bottom_navigation_bar, bottomNavContainer, true);

        // Set up navigation click listeners
        LinearLayout navHome = navView.findViewById(R.id.navHome);
        LinearLayout navFavorites = navView.findViewById(R.id.navFavorites);
        LinearLayout navPost = navView.findViewById(R.id.navPost);
        LinearLayout navChat = navView.findViewById(R.id.navChat);
        LinearLayout navAccount = navView.findViewById(R.id.navAccount);

        navHome.setOnClickListener(v -> navigateToHome());
        navFavorites.setOnClickListener(v -> navigateToFavorites());
        navPost.setOnClickListener(v -> navigateToPost());
        navChat.setOnClickListener(v -> navigateToChat());
        navAccount.setOnClickListener(v -> navigateToAccount());
    }

    private void navigateToHome() {
        Intent intent = new Intent(this, MainActivity.class);
        startActivity(intent);
        finish();
    }

    private void navigateToFavorites() {
        Intent intent = new Intent(this, MainActivity.class);
        intent.putExtra("tab", "favorites");
        startActivity(intent);
        finish();
    }

    private void navigateToPost() {
        // Already on choose category, just show a toast
        Toast.makeText(this, "Đang trên trang chọn danh mục", Toast.LENGTH_SHORT).show();
    }

    private void navigateToChat() {
        Toast.makeText(this, "Tính năng chat đang được phát triển", Toast.LENGTH_SHORT).show();
    }

    private void navigateToAccount() {
        Toast.makeText(this, "Tính năng tài khoản đang được phát triển", Toast.LENGTH_SHORT).show();
    }

    private void fetchItemTypes() {
        progressBar.setVisibility(View.VISIBLE);
        apiService.getItemTypes().enqueue(new Callback<ApiResponse<List<ItemType>>>() {
            @Override
            public void onResponse(Call<ApiResponse<List<ItemType>>> call, Response<ApiResponse<List<ItemType>>> response) {
                progressBar.setVisibility(View.GONE);
                if (response.isSuccessful() && response.body() != null) {
                    adapter.setCategories(response.body().getData());
                }
            }

            @Override
            public void onFailure(Call<ApiResponse<List<ItemType>>> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                Toast.makeText(ChooseCategoryActivity.this, "Lỗi tải danh mục", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void onCategorySelected(ItemType type) {
        Intent intent;
        String id = type.getItemTypeId();
        String name = type.getName();
        String nameLower = name.toLowerCase();

        if (nameLower.contains("ô tô")) {
            intent = new Intent(this, CreatePostActivity.class);
        } else if (nameLower.contains("phụ tùng") || nameLower.contains("phụ kiện")) {
            intent = new Intent(this, CreateAccessoryPostActivity.class);
        } else if (nameLower.contains("xe đạp")) {
            intent = new Intent(this, CreateBikePostActivity.class);
        } else if (nameLower.contains("xe điện")) {
            intent = new Intent(this, CreateElectricBikePostActivity.class);
        } else if (nameLower.contains("ắc quy") || nameLower.contains("pin")) {
            intent = new Intent(this, CreateBatteryPostActivity.class);
        } else if (nameLower.contains("xe máy")) {
            intent = new Intent(this, CreateMotoPostActivity.class);
        } else if (nameLower.contains("xe tải") || nameLower.contains("xe ben")) {
            intent = new Intent(this, CreateTruckPostActivity.class);
        } else {
            Toast.makeText(this, "Danh mục này đang được cập nhật", Toast.LENGTH_SHORT).show();
            return;
        }

        intent.putExtra("itemTypeId", id);
        intent.putExtra("categoryName", name);
        startActivity(intent);
    }
}

package com.example.a2hauto;

