        btnMiniHeaderLogin = findViewById(R.id.btnMiniHeaderLogin);
        tvHeaderAvatar = findViewById(R.id.tvHeaderAvatar);
        tvMiniHeaderAvatar = findViewById(R.id.tvMiniHeaderAvatar);
